/bin/zsh -lc "python3 - <<'PY'
from itertools import combinations

facets = [(0,1,2),(0,2,3),(0,1,5),(0,4,5),(0,3,4),(1,2,4),(1,3,4),(1,3,5),(2,3,5),(2,4,5)]
edges = [(i,j) for i in range(6) for j in range(i+1,6)]

facet_coeffs = []
for a,b,c in facets:
    coeff = {(b,c): 1, (a,c): -1, (a,b): 1}
    facet_coeffs.append(coeff)

parent = list(range(6))
def is_tree(es):
    parent = list(range(6))
    def find(x):
        while parent[x]"'!=x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def union(a,b):
        ra, rb = find(a), find(b)
        if ra==rb:
            return False
        parent[rb] = ra
        return True
    for a,b in es:
        if not union(a,b):
            return False
    r = find(0)
    return all(find(i)==r for i in range(6))

def det_bareiss(A):
    n = len(A)
    M = [row[:] for row in A]
    sign = 1
    prev = 1
    for k in range(n-1):
        pivot = k
        while pivot < n and M[pivot][k] == 0:
            pivot += 1
        if pivot == n:
            return 0
        if pivot != k:
            M[k], M[pivot] = M[pivot], M[k]
            sign *= -1
        pivot_val = M[k][k]
        for i in range(k+1, n):
            for j in range(k+1, n):
                M[i][j] = (M[i][j]*pivot_val - M[i][k]*M[k][j]) // prev
            M[i][k] = 0
        prev = pivot_val
    return sign * M[-1][-1]

for tree in combinations(edges,5):
    if not is_tree(tree):
        continue
    tree_set = set(tree)
    non_tree = [e for e in edges if e not in tree_set]
    cols = []
    for coeff in facet_coeffs:
        col = [coeff.get(e,0) for e in non_tree]
        cols.append(col)
    M = [list(row) for row in zip(*cols)]
    det = det_bareiss(M)
    if abs(det)==2:
        print('"'FOUND', tree, non_tree, det)
        for row in M:
            print(row)
        break
else:
    print('none found')
PY"

